/* lp-glass.css — shared glassmorphism landing-page styles (mobile-first) */
:root{
  --green:#064e3b;--green2:#0d9488;--ink:#0f172a;
  --amber:#f59e0b;--wa:#25D366;--wa-d:#1da851;--radius:20px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:'Source Sans 3',system-ui,sans-serif;color:var(--ink);line-height:1.65;
  -webkit-font-smoothing:antialiased;font-size:17px;padding-bottom:78px;position:relative;background:#e9f3ef;overflow-x:hidden}
body::before{content:"";position:fixed;inset:0;z-index:-2;background:
  radial-gradient(38% 34% at 8% 10%,rgba(13,148,136,.40),transparent 62%),
  radial-gradient(34% 30% at 92% 14%,rgba(245,158,11,.30),transparent 60%),
  radial-gradient(46% 42% at 84% 88%,rgba(6,95,70,.38),transparent 62%),
  radial-gradient(42% 40% at 12% 92%,rgba(45,212,191,.34),transparent 62%),
  linear-gradient(180deg,#eef7f3,#e6f1ec)}
body::after{content:"";position:fixed;inset:0;z-index:-1;opacity:.5;
  background-image:radial-gradient(rgba(255,255,255,.6) 1px,transparent 1px);background-size:30px 30px}
img{max-width:100%;height:auto}
.wrap{max-width:1080px;margin:0 auto;padding:0 20px}
.glass{background:rgba(255,255,255,.55);backdrop-filter:blur(18px) saturate(1.3);-webkit-backdrop-filter:blur(18px) saturate(1.3);
  border:1px solid rgba(255,255,255,.7);box-shadow:0 12px 40px rgba(2,44,34,.12)}
h1,h2,h3,.display{font-family:'Lexend',sans-serif;letter-spacing:-.02em}
.btn-wa{display:inline-flex;align-items:center;justify-content:center;gap:11px;background:var(--wa);color:#fff;
  padding:17px 30px;border-radius:14px;font-size:17px;font-weight:700;text-decoration:none;
  box-shadow:0 10px 30px rgba(37,211,102,.4);transition:transform .15s,box-shadow .15s;border:none;cursor:pointer;
  min-height:54px;line-height:1.1}
.btn-wa:hover{transform:translateY(-2px);box-shadow:0 14px 38px rgba(37,211,102,.5);background:var(--wa-d)}
.btn-wa svg{width:23px;height:23px;flex-shrink:0}

.hero{position:relative;color:#fff;overflow:hidden;background:linear-gradient(135deg,#064e3b 0%,#0d9488 55%,#0f766e 100%)}
.hero::before{content:"";position:absolute;inset:0;background:
  radial-gradient(60% 60% at 12% 18%,rgba(245,158,11,.32),transparent 60%),
  radial-gradient(50% 50% at 92% 12%,rgba(255,255,255,.14),transparent 55%),
  radial-gradient(60% 55% at 80% 95%,rgba(13,148,136,.55),transparent 60%)}
.hero::after{content:"";position:absolute;inset:0;opacity:.08;background-image:radial-gradient(rgba(255,255,255,.9) 1px,transparent 1px);background-size:26px 26px}
.hero-inner{position:relative;z-index:2;display:grid;grid-template-columns:1.15fr .85fr;gap:46px;align-items:center;padding:64px 0 72px}
.pill{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.32);backdrop-filter:blur(6px);color:#fff;font-size:13px;font-weight:700;padding:8px 16px;border-radius:30px;margin-bottom:20px}
.pill .dot{width:8px;height:8px;border-radius:50%;background:#4ade80;box-shadow:0 0 0 4px rgba(74,222,128,.3)}
.hero h1{font-size:clamp(2rem,7vw,3.4rem);font-weight:800;line-height:1.1;margin-bottom:18px}
.hero h1 em{font-style:normal;color:#fcd34d}
.hero .lead{font-size:clamp(1.02rem,2.2vw,1.2rem);color:rgba(255,255,255,.9);max-width:560px;margin-bottom:14px}
.hero .reassure{font-size:15px;color:rgba(255,255,255,.82);margin-bottom:26px}
.hero-cta{display:flex;align-items:center;gap:18px;flex-wrap:wrap}
.hero-cta .price-tag{font-size:14px;color:rgba(255,255,255,.85)}
.hero-cta .price-tag b{display:block;font-size:21px;font-weight:800;color:#fff;font-family:'Lexend'}
.hcard{background:rgba(255,255,255,.16);backdrop-filter:blur(20px) saturate(1.2);-webkit-backdrop-filter:blur(20px) saturate(1.2);border:1px solid rgba(255,255,255,.35);border-radius:22px;padding:24px;color:#fff;box-shadow:0 30px 60px rgba(0,0,0,.28)}
.hcard .urg{display:flex;align-items:center;gap:8px;background:rgba(245,158,11,.95);color:#3b2300;font-weight:700;font-size:13px;padding:9px 12px;border-radius:10px;margin-bottom:18px}
.hcard h3{font-size:18px;margin-bottom:12px;color:#fff}
.hcard .row{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:11px 0;border-bottom:1px solid rgba(255,255,255,.18);font-size:15px}
.hcard .row:last-of-type{border:none}
.hcard .row span{color:rgba(255,255,255,.78)}.hcard .row b{font-weight:700;color:#fff;text-align:right}
.hstats{display:flex;gap:12px;margin-top:32px;flex-wrap:wrap}
.hstat{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.22);border-radius:14px;padding:12px 16px;backdrop-filter:blur(6px)}
.hstat b{display:block;font-family:'Lexend';font-size:1.45rem;font-weight:800;line-height:1}
.hstat span{font-size:12px;color:rgba(255,255,255,.72)}

.trust{padding:24px 0}
.trust p{text-align:center;font-size:13px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:#0b5d4a;margin-bottom:14px}
.trust-logos{display:flex;flex-wrap:wrap;justify-content:center;gap:10px 12px}
.tchip{background:rgba(255,255,255,.5);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.7);border-radius:12px;padding:9px 15px;font-weight:700;font-size:14px;color:#1f3b33}

section.pad{padding:58px 0;position:relative}
.eyebrow{text-align:center;color:#0b5d4a;font-weight:700;font-size:14px;letter-spacing:.06em;text-transform:uppercase;margin-bottom:10px}
h2.title{text-align:center;font-size:clamp(1.55rem,5vw,2.2rem);font-weight:800;margin-bottom:8px;color:#0c1f1a}
.subtitle{text-align:center;color:#33514a;max-width:620px;margin:0 auto 36px;font-size:16.5px}

.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.card{border-radius:var(--radius);padding:24px;transition:transform .15s,box-shadow .15s}
.card:hover{transform:translateY(-5px);box-shadow:0 20px 46px rgba(2,44,34,.16)}
.ic{width:50px;height:50px;border-radius:14px;display:flex;align-items:center;justify-content:center;margin-bottom:15px;background:rgba(13,148,136,.16);color:#0b5d4a;border:1px solid rgba(13,148,136,.2)}
.ic svg{width:25px;height:25px}
.card h3{font-size:17.5px;font-weight:700;margin-bottom:6px;color:#0c1f1a}
.card p{font-size:15px;color:#3a554d}

.price-wrap{max-width:680px;margin:0 auto}
.price-card{border-radius:24px;padding:32px}
.price-head{display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:14px;margin-bottom:22px}
.price-head .big{font-family:'Lexend';font-size:clamp(1.9rem,6vw,2.4rem);font-weight:800;color:var(--green);line-height:1}
.price-head .big small{display:block;font-size:14px;color:#3a554d;font-weight:600;font-family:'Source Sans 3';margin-top:4px}
.badge-official{background:#064e3b;color:#fff;font-size:12px;font-weight:700;padding:8px 14px;border-radius:30px}
.incl{display:grid;grid-template-columns:1fr 1fr;gap:12px 18px;margin-bottom:24px}
.incl div{display:flex;gap:10px;align-items:flex-start;font-size:15px;color:#1f3b33}
.incl svg{width:20px;height:20px;color:var(--green2);flex-shrink:0;margin-top:2px}

.testi-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.testi{border-radius:var(--radius);padding:24px}
.stars{color:var(--amber);margin-bottom:12px;font-size:18px}
.testi p{font-size:15.5px;color:#26413a;margin-bottom:16px}
.who{display:flex;align-items:center;gap:12px}
.av{width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,#0d9488,#064e3b);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;font-family:'Lexend';flex-shrink:0}
.who b{display:block;font-size:15px;color:#0c1f1a}.who span{font-size:13px;color:#3a554d}

.faq{max-width:760px;margin:0 auto}
details{border-radius:14px;padding:2px 20px;margin-bottom:12px}
summary{font-weight:700;font-size:16.5px;padding:18px 0;cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:14px;color:#0c1f1a}
summary::-webkit-details-marker{display:none}
summary::after{content:"+";font-size:24px;color:var(--green2);font-weight:400;flex-shrink:0}
details[open] summary::after{content:"\2013"}
details p{padding:0 0 18px;color:#3a554d;font-size:15.5px}

.final{border-radius:26px;padding:48px 26px;text-align:center;color:#fff;position:relative;overflow:hidden;background:linear-gradient(135deg,#064e3b,#0d9488)}
.final::before{content:"";position:absolute;inset:0;background:radial-gradient(50% 80% at 80% 10%,rgba(245,158,11,.32),transparent 60%)}
.final>*{position:relative;z-index:1}
.final h2{font-size:clamp(1.5rem,5vw,2.3rem);font-weight:800;margin-bottom:12px;color:#fff}
.final p{font-size:17px;color:rgba(255,255,255,.9);margin-bottom:26px;max-width:560px;margin-inline:auto}

.foot{background:rgba(8,30,24,.88);backdrop-filter:blur(10px);color:#a9c4ba;padding:32px 0;font-size:14px;text-align:center;margin-top:10px}
.foot a{color:#d7e6df;text-decoration:none;margin:0 7px}
.foot .links{margin-bottom:12px;line-height:2}

.sticky{position:fixed;left:0;right:0;bottom:0;z-index:50;background:rgba(255,255,255,.78);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border-top:1px solid rgba(255,255,255,.8);box-shadow:0 -6px 24px rgba(0,0,0,.1);padding:9px 14px;display:flex;align-items:center;gap:12px;justify-content:space-between}
.sticky .info{font-size:12.5px;color:#3a554d;line-height:1.25;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.sticky .info b{display:block;color:#0c1f1a;font-size:14.5px;font-weight:800;font-family:'Lexend';overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.sticky .btn-wa{padding:12px 20px;font-size:15px;box-shadow:none;flex-shrink:0;min-height:46px;white-space:nowrap}

/* ============ MOBILE ============ */
@media(max-width:860px){
  .hero-inner{grid-template-columns:1fr;gap:28px;padding:42px 0 48px;text-align:center}
  .hero .lead{margin-inline:auto}
  .hero-cta{justify-content:center;flex-direction:column;gap:14px}
  .hero-cta .btn-wa{width:100%}
  .hstats{justify-content:center}
  .cards{grid-template-columns:1fr 1fr}
  .testi-grid{grid-template-columns:1fr}
  .sticky{justify-content:space-between}
}
@media(min-width:861px){.sticky{justify-content:center;gap:28px}}
@media(max-width:560px){
  .wrap{padding:0 16px}
  section.pad{padding:44px 0}
  .cards{grid-template-columns:1fr}
  .incl{grid-template-columns:1fr}
  .price-card{padding:24px}
  .price-head{flex-direction:column}
  .btn-wa{width:100%}
  .hcard .row b{font-size:14.5px}
  .trust-logos{gap:8px}
  .tchip{font-size:13px;padding:8px 12px}
}

.k3-search{display:flex;gap:10px;max-width:560px;margin:22px auto 0;flex-wrap:wrap}
.k3-search input{flex:1;min-width:200px;padding:14px 18px;border-radius:12px;border:1px solid rgba(255,255,255,.4);background:rgba(255,255,255,.9);font-size:15px}
.k3-search button{border:none;cursor:pointer}
.prog-group{margin-bottom:34px}
.prog-group h3{font-family:'Lexend',sans-serif;font-size:1.15rem;color:#0b5d4a;margin-bottom:14px;display:flex;align-items:center;gap:10px}
.prog-group h3 .cnt{font-size:12px;font-weight:600;background:rgba(13,148,136,.15);color:#0b5d4a;padding:3px 10px;border-radius:20px}
.prog-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px}
.prog-item{border-radius:14px;padding:16px 18px;display:flex;flex-direction:column;gap:6px}
.prog-item .pn{font-weight:700;color:#0c1f1a;font-size:15px;line-height:1.35}
.prog-item .meta{display:flex;gap:8px;flex-wrap:wrap;font-size:12px;color:#3a554d}
.prog-item .meta b{color:var(--green)}
.prog-item .pcta{display:flex;gap:8px;margin-top:6px;flex-wrap:wrap}
.prog-item .mini{font-size:13px;padding:8px 14px;border-radius:9px;min-height:0}
.mini-out{background:rgba(6,78,59,.08);color:var(--green);font-weight:700;text-decoration:none;display:inline-flex;align-items:center;padding:8px 14px;border-radius:9px;font-size:13px}
.kw-index{columns:2;column-gap:26px;max-width:900px;margin:0 auto}
.kw-index .kw-mod{break-inside:avoid;margin-bottom:18px}
.kw-index h4{font-family:'Lexend',sans-serif;font-size:14px;color:#0b5d4a;text-transform:capitalize;margin-bottom:8px}
.kw-index a{display:block;font-size:13.5px;color:#33514a;text-decoration:none;padding:3px 0}
.kw-index a:hover{color:var(--green2)}
@media(max-width:560px){.kw-index{columns:1}}
.demand-note{max-width:760px;margin:0 auto 8px;text-align:center;font-size:14px;color:#3a554d}
.prog-more{margin-top:6px}
.prog-more summary{font-size:14px;padding:12px 0;color:var(--green)}
.prog-more summary::after{color:var(--green2)}
.prog-more .prog-list{margin-top:10px}

/* --- Contrast fix: ad traffic often lands via Facebook/Instagram/TikTok
   in-app browsers, which frequently have weak or no backdrop-filter support.
   Without it, .glass falls back to a thin 55%-opacity white sheet over the
   busy gradient background, and small gray text becomes hard to read. Force
   a near-opaque, high-contrast fallback whenever blur isn't actually applied,
   and unconditionally strengthen text darkness on small viewports. */
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .glass{background:rgba(255,255,255,.96)}
}
@media(max-width:860px){
  .glass{background:rgba(255,255,255,.88)}
  .prog-item .meta{color:#1f3b33;font-weight:600}
  .prog-item .meta b{color:#064e3b}
  .kw-index a{color:#1f3b33}
  .demand-note{color:#1f3b33}
  .card p{color:#1f3b33}
  .testi p{color:#1f3b33}
  .subtitle{color:#26413a}
}
